CREATE TABLE IF NOT EXISTS intents (id BIGSERIAL PRIMARY KEY, intent_id TEXT NOT NULL, intent_hash TEXT NOT NULL UNIQUE, schema_version TEXT NOT NULL, chain_id BIGINT NOT NULL, action TEXT NOT NULL, sender TEXT NOT NULL, recipient TEXT NOT NULL, asset TEXT NOT NULL, amount TEXT NOT NULL, nonce TEXT NOT NULL, valid_until BIGINT NOT NULL, constraints_json JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS execution_observations (id BIGSERIAL PRIMARY KEY, intent_hash TEXT NOT NULL, chain_id BIGINT NOT NULL, tx_hash TEXT NOT NULL, status TEXT NOT NULL, block_number BIGINT, observed_at BIGINT, finality_state TEXT, observation_json JSONB NOT NULL, outcome TEXT, reason_codes JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS execution_chain_tx_idx ON execution_observations(chain_id, tx_hash);
CREATE TABLE IF NOT EXISTS receipts (receipt_id TEXT PRIMARY KEY, intent_hash TEXT NOT NULL, tx_hash TEXT NOT NULL, schema TEXT NOT NULL, issuer TEXT NOT NULL, key_id TEXT NOT NULL, outcome TEXT NOT NULL, receipt_json JSONB NOT NULL, signature TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
